WFJ.Data.add("book", {
  ["fa01b212f5c1f02c"] = { "ぼろぼろになり散り散りになったオークの生き残りには、オークの力の最後の砦――dark portalへ逃げる以外に道はなかった。\n\nTuralyonとウォリアーたちは、残ったオークを追って腐臭漂うSwamp of Sorrowsを抜け、dark portalのそびえる堕落したBlasted Landsへと進んだ。そこで、巨大な門のふもとで、崩れた大軍と屈強なAllianceが、Second War最後にして最も血なまぐさい戦いで激突した。", "." },
  ["fa04e6adc61f5a1b"] = { "Arathorの人間社会は成長し繁栄したが、Thoradinは王国が手を広げすぎれば分裂してしまうことを恐れ、StromこそがArathorianの帝国の中心であるという立場を守った。成長と交易の平和な年月が長く続いた後、偉大なThoradinは老衰で世を去り、Arathorの若い世代はStromの地を越えて帝国を拡大できるようになった。", "." },
  ["fa2003540902ff7c"] = { "では、なぜこのようなことを記すのか。それは、これから書くことに信憑性を持たせるためである。この言葉はKeganの口から出たものであり、同僚諸氏がこの日誌を読んで、私がなぜ彼の言葉を信じるのかを理解してくれることを願っている。\n\n「Old Godsの名残は、今なお世界の深い洞に潜んでいる。新たな勢力がその古の力を利用しようとしており、それに成功した者は、敵に対して恐るべき武器を手にすることになるだろう」", "." },
  ["fa43cf1e9723add5"] = { "民の再生を象徴するため、ThrallはBlackmooreの砦Durnholdeへ戻り、収容所を包囲することで、かつての主の企みにきっぱりと終止符を打った。この勝利には代償が伴った。ある収容所の解放の最中に、Doomhammerが戦死したのである。", "." },
  ["fa6df2374a282dfc"] = { "この手紙が無事に届くことを願っています、{class}。これは大きな誇りを込めて言うのです。それほど深い信仰を公言できる者は多くありませんが、そのような者こそがAzerothの守り手の中でも最も精鋭の者たちだと知っておいてほしいからです。\n\n常に覚えておきなさい。何よりもまず、我々の世界を害し、我々の家に堕落をもたらそうとする者たちと戦うことが、あなたの務めなのです。\n\n当面の間、あなたの訓練を任されることになりました。準備ができたら、Northshire Abbeyの中で私を探してください。\n\n-パラディンのトレーナー、Brother Sammuel", "." },
  ["fac5d66b10f96ba6"] = { "私の言葉を無視せぬよう気をつけろ、{name}。今は全ての国々で策略と欺瞞が渦巻く時代だ……我らの偉大なUndercityでさえな。Sylvanasに忠誠を誓う者は皆、Forsakenが支配する新たな時代を築くために動いている。我らは魔法の技を持たず、国境で武器を取ることもないが、それでも果たすべき役割がある。\n\nDeathknellの宿屋で私を探せ。話の続きはそこでしよう。\n\n-ローグのトレーナー、David Trias", "." },
  ["fad9a9de972623f1"] = { "Galvanized Horn:\n\n希少な電気を帯びた角の頑丈さは、私が作る鎧全体の要であり、これもまた手に入れねばならない。\n\nCharred Valeにいる希少なchimaeraの女家長から得られるだろう。", "." },
  ["faf50f0a266d742e"] = { "furbolgはDartolを殺しただけでなく、杖が二度と自分たちに向けて使われないよう、3つの部分に分けてしまった。苦労はしたが、3つの部分がそれぞれどこに置かれたのか、おおよその見当はついている。\n\n宝石\n杖の最初の部分である輝く宝石は、Ashenvale北西部の祠に隠された。今では、その祠はLake Falathimの中央にある遺跡だと考えている。Sentinelsによれば、そこには今murlocが住み着いているそうだ。", "." },
